module counter_8bit #(
    parameter WIDTH = 8
)(
    input  wire             clk,        // Clock
    input  wire             rst_n,      // Active-low reset
    input  wire             enable,     // Count enable
    input  wire             load,       // Load preset value
    input  wire [WIDTH-1:0] load_value, // Preset value to load
    input  wire [1:0]       mode,       // Counter mode
    output reg  [WIDTH-1:0] count,      // Current count value
    output wire             overflow,   // Overflow flag
    output wire             zero        // Zero flag
);

    // Internal signals
    reg direction;  // 0: up, 1: down (for UP-DOWN mode)
    reg overflow_reg;
    
    // Local parameters for modes
    localparam MODE_UP      = 2'b00;
    localparam MODE_DOWN    = 2'b01;
    localparam MODE_UP_DOWN = 2'b10;
    
    // Zero flag assignment
    assign zero = (count == {WIDTH{1'b0}});
    
    // Overflow flag assignment
    assign overflow = overflow_reg;
    
    // Main counter logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= {WIDTH{1'b0}};
            direction <= 1'b0;
            overflow_reg <= 1'b0;
        end else begin
            overflow_reg <= 1'b0;
            
            if (load) begin
                count <= load_value;
                // Reset direction for UP-DOWN mode when loading
                if (mode == MODE_UP_DOWN) begin
                    direction <= 1'b0;
                end
            end else if (enable) begin
                case (mode)
                    MODE_UP: begin
                        count <= count + 1'b1;
                        if (count == {WIDTH{1'b1}}) begin
                            overflow_reg <= 1'b1;
                        end
                    end
                    
                    MODE_DOWN: begin
                        count <= count - 1'b1;
                        if (count == {WIDTH{1'b0}}) begin
                            overflow_reg <= 1'b1;
                        end
                    end
                    
                    MODE_UP_DOWN: begin
                        if (direction == 1'b0) begin
                            // Counting up
                            count <= count + 1'b1;
                            if (count == {WIDTH{1'b1}}) begin
                                direction <= 1'b1;
                                overflow_reg <= 1'b1;
                            end
                        end else begin
                            // Counting down
                            count <= count - 1'b1;
                            if (count == {WIDTH{1'b0}}) begin
                                direction <= 1'b0;
                                overflow_reg <= 1'b1;
                            end
                        end
                    end
                    
                    default: begin
                        // Default to UP mode
                        count <= count + 1'b1;
                        if (count == {WIDTH{1'b1}}) begin
                            overflow_reg <= 1'b1;
                        end
                    end
                endcase
            end
        end
    end

endmodule